<?php
declare(strict_types=1);$active_module='room_rack';require_once __DIR__.'/layout.php';if(empty($_SESSION['supplier_csrf']))$_SESSION['supplier_csrf']=bin2hex(random_bytes(32));$u=$supplier_user;$pdo=db();$date=$_GET['date']??date('Y-m-d');$notice='';$error='';
try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['supplier_csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Güvenlik doğrulaması geçersiz.');if($_POST['action']==='group'){$pdo->prepare('INSERT INTO booking_groups(supplier_id,property_id,group_code,group_name,status,option_expires_at) VALUES(?,?,?,?,?,?)')->execute([$u['supplier_id'],(int)$_POST['property_id'],strtoupper(trim((string)$_POST['group_code'])),trim((string)$_POST['group_name']),$_POST['status']==='confirmed'?'confirmed':'option',$_POST['option_expires_at']?:null]);$notice='Grup kartı oluşturuldu.';}if($_POST['action']==='move'){$pdo->beginTransaction();$q=$pdo->prepare('SELECT br.physical_room_id,br.id booking_room_id,b.supplier_id,b.id booking_id,b.check_in,b.check_out FROM booking_rooms br JOIN supplier_bookings b ON b.id=br.booking_id WHERE br.id=? FOR UPDATE');$q->execute([(int)$_POST['booking_room_id']]);$r=$q->fetch();if(!$r||$r['supplier_id']!=$u['supplier_id'])throw new RuntimeException('Rezervasyon odası bulunamadı.');$toRoom=(int)$_POST['to_room_id'];$conflict=$pdo->prepare("SELECT 1 FROM booking_rooms br JOIN supplier_bookings b ON b.id=br.booking_id WHERE br.physical_room_id=? AND br.booking_id<>? AND b.booking_status NOT IN ('cancelled','no_show','checked_out') AND b.check_in<? AND b.check_out>? LIMIT 1");$conflict->execute([$toRoom,$r['booking_id'],$r['check_out'],$r['check_in']]);if($conflict->fetch())throw new RuntimeException('Hedef oda bu tarihlerde dolu; oda taşınamaz.');$pdo->prepare('INSERT INTO booking_room_moves(booking_room_id,from_physical_room_id,to_physical_room_id,reason,moved_by) VALUES(?,?,?,?,?)')->execute([(int)$_POST['booking_room_id'],$r['physical_room_id'],$toRoom,trim((string)$_POST['reason'])?:null,$u['id']]);$pdo->prepare('UPDATE booking_rooms SET physical_room_id=? WHERE id=?')->execute([$toRoom,(int)$_POST['booking_room_id']]);$pdo->commit();$notice='Oda değişikliği işlendi.';}}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
$q=$pdo->prepare("SELECT id,name FROM properties WHERE supplier_id=? AND property_type='hotel' ORDER BY name");$q->execute([$u['supplier_id']]);$hotels=$q->fetchAll();$property=(int)($_GET['property']??($hotels[0]['id']??0));$q=$pdo->prepare("SELECT pr.*,rt.name room_type_name,b.id booking_id,b.booking_reference,b.booking_status,br.id booking_room_id,g.first_name,g.last_name FROM physical_rooms pr LEFT JOIN room_types rt ON rt.id=pr.room_type_id LEFT JOIN booking_rooms br ON br.physical_room_id=pr.id LEFT JOIN supplier_bookings b ON b.id=br.booking_id AND b.check_in<=? AND b.check_out>? AND b.booking_status NOT IN ('cancelled','no_show','checked_out') LEFT JOIN booking_guests bg ON bg.booking_id=b.id AND bg.is_primary=true LEFT JOIN guest_profiles g ON g.id=bg.guest_id WHERE pr.property_id=? ORDER BY pr.room_number");$q->execute([$date,$date,$property]);$rack=$q->fetchAll();supply_start('Room Rack & grup rezervasyon',$active_module);?>
<section class="page-intro"><p>Fiziksel odaları, güncel doluluğu ve oda değişikliklerini gün bazında yönetin.</p></section><?php if($notice):?><p class="save-success">✓ <?=htmlspecialchars($notice)?></p><?php endif;?><?php if($error):?><p class="login-error"><?=htmlspecialchars($error)?></p><?php endif;?><form method="get" class="supply-form"><select name="property"><?php foreach($hotels as $h):?><option value="<?=$h['id']?>" <?=$h['id']==$property?'selected':''?>><?=htmlspecialchars($h['name'])?></option><?php endforeach;?></select><input type="date" name="date" value="<?=htmlspecialchars($date)?>"><button>Oda planını aç</button></form><section class="next-module"><h2><?=htmlspecialchars($date)?> oda planı</h2><?php foreach($rack as $r):?><article><b><?=htmlspecialchars($r['room_number'])?></b> · <?=htmlspecialchars($r['room_type_name']??'—')?> · <strong><?=htmlspecialchars($r['status'])?></strong><?php if($r['booking_id']):?><p><?=htmlspecialchars($r['booking_reference'])?> · <?=htmlspecialchars(trim(($r['first_name']??'').' '.($r['last_name']??'')))?> · <?=htmlspecialchars($r['booking_status'])?></p><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="move"><input type="hidden" name="booking_room_id" value="<?=$r['booking_room_id']?>"><input type="number" name="to_room_id" placeholder="Yeni oda ID" required><input name="reason" placeholder="Oda değişim nedeni"><button>Odayı taşı</button></form><?php endif;?></article><?php endforeach;?></section><section class="next-module"><h2>Grup kartı</h2><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="group"><select name="property_id"><?php foreach($hotels as $h):?><option value="<?=$h['id']?>"><?=htmlspecialchars($h['name'])?></option><?php endforeach;?></select><input name="group_code" placeholder="GRP-2026-001" required><input name="group_name" placeholder="Grup adı" required><select name="status"><option value="option">Opsiyon</option><option value="confirmed">Konfirme</option></select><input type="datetime-local" name="option_expires_at"><button>Grup kartı oluştur</button></form></section><section class="next-module"><h2>Oda çakışması raporu</h2>
<?php $cq=$pdo->prepare("SELECT pr.room_number,a.booking_reference a_ref,b.booking_reference b_ref,a.check_in a_in,a.check_out a_out,b.check_in b_in,b.check_out b_out FROM supplier_bookings a JOIN booking_rooms ar ON ar.booking_id=a.id JOIN physical_rooms pr ON pr.id=ar.physical_room_id JOIN booking_rooms br2 ON br2.physical_room_id=pr.id JOIN supplier_bookings b ON b.id=br2.booking_id AND b.id<>a.id WHERE a.supplier_id=? AND a.booking_status NOT IN ('cancelled','no_show','checked_out') AND b.booking_status NOT IN ('cancelled','no_show','checked_out') AND a.check_in<b.check_out AND b.check_in<a.check_out ORDER BY pr.room_number");$cq->execute([$u['supplier_id']]);$conflicts=$cq->fetchAll();?>
<?php if(!$conflicts):?><p class="muted">Aktif rezervasyonlar arasında oda çakışması yok.</p><?php endif;?>
<?php foreach($conflicts as $c):?><p class="login-error"><b><?=htmlspecialchars($c['room_number'])?></b>: <?=htmlspecialchars($c['a_ref'])?> (<?=htmlspecialchars($c['a_in'])?>–<?=htmlspecialchars($c['a_out'])?>) ↔ <?=htmlspecialchars($c['b_ref'])?> (<?=htmlspecialchars($c['b_in'])?>–<?=htmlspecialchars($c['b_out'])?>)</p><?php endforeach;?>
</section><?php supply_end();
